// ============================================================
// 🔑 مفاتيح الـ API الاحتياطية (تشتغل تلقائياً إذا المفتاح الأساسي في AI Agent وصل الحد!)
// ============================================================
const API_KEYS = [
  "PUT_BACKUP_API_KEY_1_HERE",
  "PUT_BACKUP_API_KEY_2_HERE",
  "PUT_BACKUP_API_KEY_3_HERE",
  "PUT_BACKUP_API_KEY_4_HERE",
  "PUT_BACKUP_API_KEY_5_HERE",
  "PUT_BACKUP_API_KEY_6_HERE"
];

const MODELS = [
  "gemini-3.6-flash",
  "gemini-3.1-flash-lite",
  "gemini-2.5-flash",
  "gemini-2.5-flash-lite"
];

const SYSTEM_PROMPT = `أنت 'نانو' (Nano)، الذكاء الاصطناعي المحلي الطائر من فريق Agentic Mind لطلاب الجامعات في الأردن (تخصصي تكنولوجيا المعلومات والأعمال).
فكرتك: ذكاء اصطناعي محلي يحفظ خصوصية المستخدم بدون إرسال بياناته للشركات، يتعلم من صاحبه ويُربّى على إيديه، ويساعد الإنسان دون أن يستبدله.
أجب بلطف واختصار ووضوح بالعربية (أو الإنجليزية إذا خاطبك المستخدم بها).`;

// قراءة رسالة المستخدم الأصلية مباشرة من Chat Trigger
let userMessage = "مرحبا";
try {
  userMessage = $('When chat message received').first().json.chatInput || userMessage;
} catch (e) {
  userMessage = $input.first().json.chatInput || userMessage;
}

const validKeys = API_KEYS.filter(k => k && !k.startsWith("PUT_BACKUP_API_KEY_"));

let replyText = null;
let usedKeyIndex = -1;
let usedModel = null;

for (let i = 0; i < validKeys.length && !replyText; i++) {
  const apiKey = validKeys[i];
  for (let m = 0; m < MODELS.length && !replyText; m++) {
    const model = MODELS[m];
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url,
        headers: { 'Content-Type': 'application/json' },
        body: {
          systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
          contents: [{ role: 'user', parts: [{ text: userMessage }] }],
          generationConfig: { temperature: 0.6, maxOutputTokens: 450 }
        },
        json: true,
        timeout: 15000
      });

      const candidate = res?.candidates?.[0]?.content?.parts?.[0]?.text;
      if (candidate) {
        replyText = candidate.trim();
        usedKeyIndex = i + 1;
        usedModel = model;
      }
    } catch (err) {
      continue;
    }
  }
}

if (!replyText) {
  replyText = "أهلاً بك! 👋 أنا نانو، الذكاء الاصطناعي المحلي الطائر من فريق Agentic Mind 🛸✨\nبياناتك بتضل عندك بخصوصية 100%، وأنا هنا لأساعد طلاب الـ IT والأعمال في أفكار الأتمتة والمشاريع الذكية!";
}

return [{ json: { output: replyText, usedKeyIndex, usedModel } }];
